import 'package:csv/csv.dart'; import 'package:flutter/material.dart'; import '../models/report.dart'; import '../services/report_service.dart'; import '../utils/constants.dart'; import '../widgets/report_card.dart'; import 'dashboard_report_details_screen.dart';
class DashboardScreen extends StatefulWidget { const DashboardScreen({super.key}); @override State<DashboardScreen> createState()=>_DashboardScreenState(); }
class _DashboardScreenState extends State<DashboardScreen>{late Future<List<IncidentReport>> reports; @override void initState(){super.initState();reports=ReportService().all();} void refresh()=>setState(()=>reports=ReportService().all());
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Responder Dashboard'),actions:[IconButton(onPressed:refresh,icon:const Icon(Icons.refresh))]),body:FutureBuilder<List<IncidentReport>>(future:reports,builder:(c,s){if(s.connectionState!=ConnectionState.done)return const Center(child:CircularProgressIndicator());if(s.hasError)return const Center(child:Text('Unable to load responder reports. Your role may not have access.'));final data=s.data!;final stats=[['Total Reports',data.length,Colors.blue],['Pending',data.where((r)=>r.status=='PENDING').length,Colors.orange],['Active',data.where((r)=>activeStatuses.contains(r.status)).length,Colors.purple],['Resolved',data.where((r)=>r.status=='RESOLVED').length,Colors.green]];return LayoutBuilder(builder:(c,size)=>Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Live incident receiving system',style:Theme.of(c).textTheme.headlineSmall),const Text('Received timestamps and GPS coordinates are actual values stored with each report.'),const SizedBox(height:16),Wrap(spacing:10,runSpacing:10,children:stats.map((e)=>SizedBox(width:size.maxWidth>700?180:(size.maxWidth-42)/2,child:Card(color:(e[2] as Color).withOpacity(.08),child:Padding(padding:const EdgeInsets.all(14),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(e[0] as String),Text('${e[1]}',style:Theme.of(c).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold))])))).toList()),const SizedBox(height:12),Expanded(child:data.isEmpty?const Center(child:Text('No received reports.')):ListView(children:data.map((r)=>ReportCard(report:r,onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>DashboardReportDetailsScreen(report:r,onChanged:refresh)))).toList()))])));}));}

// CSV text can be copied/downloaded by a browser integration without inventing test outcomes.
String reportsCsv(List<IncidentReport> reports)=>const ListToCsvConverter().convert([['report_id','incident_type','status','submitted_at','received_at','delivery_time_ms','latitude','longitude','gps_accuracy_m'],...reports.map((r)=>[r.reportId,r.incidentType,r.status,r.createdAt.toIso8601String(),r.receivedAt?.toIso8601String(),r.receivedAt?.difference(r.createdAt).inMilliseconds,r.latitude,r.longitude,r.locationAccuracy])]);
